ADMIN_JS = r"""
<script>
(()=>{
  const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('.topbar nav');
  menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Закрыть меню':'Меню';});
  for(const input of document.querySelectorAll('input[type=file]')){
    const note=document.createElement('span');note.className='file-selection';note.setAttribute('aria-live','polite');input.insertAdjacentElement('afterend',note);
    input.addEventListener('change',()=>{const files=[...input.files];const names=files.map(f=>`${f.name} · ${(f.size/1048576).toFixed(1)} МБ`);note.textContent=names.length?`Выбрано: ${names.join(', ')}`:'';note.classList.toggle('selected',!!names.length);input.classList.toggle('has-file',!!names.length);});
  }
  const search=document.querySelector('#text-search');
  search?.addEventListener('input',()=>{const term=search.value.trim().toLocaleLowerCase('ru');for(const group of document.querySelectorAll('.text-group')){let visible=0;for(const card of group.querySelectorAll('.text-card')){const match=!term||card.dataset.search.includes(term);card.hidden=!match;if(match)visible++;}group.hidden=!!term&&!visible;if(term&&visible)group.open=true;}});
  function toast(message,isError=false){const box=document.createElement('div');box.className='toast'+(isError?' error':'');box.setAttribute('role','status');box.textContent=message;document.body.append(box);setTimeout(()=>box.remove(),5000);}
  const saved=sessionStorage.getItem('adminNotice');if(saved){sessionStorage.removeItem('adminNotice');toast(saved);}
  document.addEventListener('submit',event=>{
    const form=event.target;if(!(form instanceof HTMLFormElement)||form.method.toLowerCase()!=='post')return;
    if(form.dataset.requireFile==='true'&&![...form.querySelectorAll('input[type=file]')].some(input=>input.files?.length)){
      event.preventDefault();let message=form.querySelector('.form-feedback');if(!message){message=document.createElement('div');message.className='form-feedback error';message.setAttribute('role','alert');form.append(message);}message.classList.add('error');message.textContent='Сначала выберите файл для загрузки.';return;
    }
    const button=event.submitter||form.querySelector('button[type=submit],button:not([type])');
    if(form.dataset.submitting==='1'){event.preventDefault();return;}form.dataset.submitting='1';
    const original=button?.textContent||'Сохранить';const uploading=[...form.querySelectorAll('input[type=file]')].some(input=>input.files?.length);
    if(button){button.disabled=true;button.classList.add('is-working');button.textContent=uploading?'Загружаем…':/отправ|подтверд/i.test(original)?'Подтверждаем…':'Сохраняем…';}
    let feedback=form.querySelector('.form-feedback');if(!feedback){feedback=document.createElement('div');feedback.className='form-feedback';feedback.setAttribute('role','status');feedback.setAttribute('aria-live','polite');form.append(feedback);}feedback.classList.remove('error');feedback.textContent=uploading?'Файл отправляется на сервер…':'Сохраняем изменения…';
    if(form.dataset.nativeSubmit==='true')return;
    event.preventDefault();
    const xhr=new XMLHttpRequest();xhr.open('POST',form.action);xhr.withCredentials=true;
    let progress;
    if(uploading){progress=document.createElement('div');progress.className='form-progress indeterminate';progress.innerHTML='<span></span>';feedback.append(progress);xhr.upload.onprogress=e=>{if(e.lengthComputable){progress.classList.remove('indeterminate');progress.firstElementChild.style.width=Math.max(8,Math.round(e.loaded/e.total*100))+'%';}};}
    const restore=(message)=>{form.dataset.submitting='0';if(button){button.disabled=false;button.classList.remove('is-working');button.textContent=original;}feedback.classList.add('error');feedback.textContent=message;feedback.scrollIntoView({block:'nearest',behavior:'smooth'});};
    xhr.onerror=()=>restore('Нет связи с сервером. Проверьте подключение и повторите действие.');
    xhr.onload=()=>{
      if(xhr.status<200||xhr.status>=300){let detail='Не удалось выполнить действие. Проверьте поля и попробуйте снова.';try{const value=JSON.parse(xhr.responseText);if(typeof value.detail==='string')detail=value.detail;}catch(_){}restore(detail);return;}
      const target=new URL(xhr.responseURL||form.action,location.href);
      if(target.origin!==location.origin){restore('Неожиданный ответ сервера. Обновите страницу.');return;}
      if(target.pathname==='/admin/login'){location.assign(target.href);return;}
      sessionStorage.setItem('adminNotice',uploading?'Файлы загружены и сохранены.':/отправ|подтверд/i.test(original)?'Действие подтверждено.':'Изменения сохранены.');
      location.assign(target.href);
    };
    xhr.send(new FormData(form));
  });
})();
</script>
"""

